import math

def logsumexp(xs):
 m=max(xs)
 return m+math.log(sum(math.exp(x-m) for x in xs))
def estimate(q,z,t,delta=1e-9):
 results=[]
 for a in range(2,129):
  v=[math.lgamma(a+1)-math.lgamma(i+1)-math.lgamma(a-i+1)+i*math.log(q)+(a-i)*math.log1p(-q)+(i*i-i)/(2*z*z) for i in range(a+1)]
  rdp=t*logsumexp(v)/(a-1)
  basic=rdp+math.log(1/delta)/(a-1)
  improved=rdp-(math.log(delta)+math.log(a))/(a-1)+math.log1p(-1/a)
  results.append((a,basic,improved))
 return {'basic':min(results,key=lambda v:v[1]),'improved':min(results,key=lambda v:v[2])}
for q,z,t in [(1024/34753,1.024,2006),(204800/6950600,2.048,2006),(204800/69506000,.6144,2034)]:
 print({'q':q,'z':z,'T':t,**estimate(q,z,t)})
print('Corollary schedule for L=1, T_local=10, T=2000:', {'eta_local_T_local':math.sqrt(10/2000),'kappa':1-8*(1-math.sqrt(10/2000))**2})
